:root{
    --primary: #64adb7;
    --title: #7e868a;
    --secondary: #e2eaec;
    --ternary: #f1f3f5;
    --back: url("../../../images/widgets/default/agendas/atras.svg");
    --calendar: url("../../../images/widgets/default/datetime/calendar_widget.svg");
    --uncheck: url("../../../images/widgets/default/agendas/check_02.png") 0px 0px no-repeat;
    --check: url("../../../images/widgets/default/agendas/check_02.png") 0px -16px no-repeat;
    --input: #f5f6f7;
    --hover: #4799A4;
    --notification: #d9fff8;
    --warning: #ffe5d4;
    --warningText: #bf5814;
    --errorBack: #F4DBD0;
    --errorFont: #B4571A;
    --head: #7C8589;
    --okBack:#DAE8E8;
    --okFont:#63ACB6;
    --heightInput:32px;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer{
    width: 750px;
    margin: 0 auto;
    position: relative;
    border: 1.5px solid var(--secondary);
    border-radius: 5px;
    background-color: white;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer #idBktWidgetDefaultHeader{
    margin-top: 15px;
    margin-bottom: 15px;
    background-color: white;
    font-size: 1.8rem;
    color: var(--primary);
    font-weight: bold;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer #idDivBktServicesContainer #idListServices .clsBktServiceName a{
    font-weight: bold;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer #idBktWidgetDefaultHeader #idBktWidgetDefaultHeaderCenterName #idBktWidgetDefaultHeaderCenterNameText{
    color: var(--primary);
    font-size: 1.4rem;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer #idBktWidgetDefaultContainer{
    background-color: white;
    padding-bottom: 20px;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer #idBktWidgetDefaultFooter{
    background-color: white;
    border-top: 1.5px solid var(--secondary);
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivSubHeader{
    background-color: white;
    border: solid var(--secondary);
    border-width: 1.5px 0 1.5px 0;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivBackButton, 
#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivContinueButton{
    background: #268bd2;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivBackButton, 
#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivContinueButton:hover{
    background: var(--hover);
}

.clsDivBktSummaryAppointmentFirst .clsDivBktSummaryAppointmentRow{
    /*display: none;*/
}

div.clsDivBktSummaryAppointmentFirst > div:first-child{
    /*display: block !important;*/
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivBktDefaultSignUpRow .clsDivBktSignupFormInputDropAndTextFieldSelect, 
#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivBktDefaultSignUpHalvedRow .clsDivBktSignupFormInputDropAndTextFieldSelect{
    padding-right: 10px;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivBktDefaultSignUpRow .clsDivBktSignupFormInputDropAndTextFieldSelect select, 
#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivBktDefaultSignUpHalvedRow .clsDivBktSignupFormInputDropAndTextFieldSelect select{
    height: var(--heightInput);
    border-radius: 5px;
    background-color: var(--input);
    border: none;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivBktDefaultSignUpRow .clsDivBktSignupFormInputDropContainer select{
    height: var(--heightInput);
    border-radius: 5px;
    background-color: var(--input);
    border: none;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivBktSignupFormInputDropAndTextFieldInput{
    padding-left: 0px;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer #idDivBktSummaryAppointmentsContainer .clsDivBktSummaryAppointmentRowPeople{
    display: block !important;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer #idDivBktServicesContainer #idListServices .clsBktServiceName{
    color: var(--title);
    font-weight: bold;
    padding-right: 10px;
    box-sizing: border-box;
    text-align: center;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer #idDivBktServicesContainer #idListServices .clsBktServicePublicPrice{
    color: var(--primary);
    margin-left: 0px;
    padding-right: 25px;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsBktServiceDataContainer{
    /*margin-top: 15px;*/
    margin-top: 0px;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsBktServiceDataContainer{
    border: 1.5px solid var(--secondary);
    background-color: white;
    border-radius: 5px;
    margin-bottom: 15px;
    padding-bottom: 10px;
    padding-top: 10px;
    padding-left: 10px;
    cursor: pointer;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer #idDivBktServicesContainer #idListServices .clsBktServiceHasDescription{
    border: 1.5px solid var(--secondary);
    background-color: white;
    border-radius: 5px;
    margin-bottom: 10px;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer #idDivBktServicesContainer #idListServices .clsBktServiceHasDescription:hover{
    background-color: var(--ternary);
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsBktServiceDataContainer:hover{
    background-color: var(--ternary);
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer #idDivBktServicesContainer #idListServices .clsBktServiceGroupName{
    margin-bottom: 15px;
    color: var(--primary);
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer #idDivBktServicesContainer #idListServices .clsBktServiceDescription{
    padding-left: 5px;
    margin-top: 0px;
    padding-top: 15px;
    color: #9AAAAF;
    font-size: 0.933em;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer #idDivBktServicesContainer #idListServices .clsBktServiceDescription div{
    color: #9AAAAF;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivSubHeaderBreadcrumbsText{
    color: var(--title);
    border-left: 1.5px solid var(--secondary);
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivSubHeaderBackButton{
    height: 22px;
    float: left;
    width: 30px;
    color: var(--secondary);
    /*-webkit-mask: var(--back) no-repeat;*/
    /*mask: var(--back) no-repeat;*/
    /*background-color: var(--title);*/
    background-color: #FFF;
    background-repeat: no-repeat;
    background-position: 50% center;
    background-image: url("../../../images/widgets/default/agendas/atras.svg");
    cursor: pointer;
    max-width: 10%;
    margin-top: 8px;
    margin-left: 10px;
    margin-right: 10px;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivBktAgendaDataImageContainer{
    /*margin-left: 10px;*/
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivBktAgendaContentImage{
    /*width: 50px;*/
    /*height: 50px;*/
    /*border-radius: 50%;*/
    border-bottom-left-radius: 5px;
    border-top-left-radius: 5px;
    background: none;
    /*margin: auto;*/
    border-left: 1.5px solid var(--secondary);
    border-top: 1.5px solid var(--secondary);
    border-bottom: 1.5px solid var(--secondary); 
    text-align: center;
    height: 68px;
    width: 70px;
    display: table;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivBktAgendaContentImage img{
    width: 50px;
    /*height: 50px;*/
    height: 68px;
    /*object-fit: cover;*/
    /*border-radius: 50%;*/
    /*border: 1px solid var(--secondary);*/
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivBktAgendaContentImageCell{
    text-align: center;
    display: table-cell;
    vertical-align: middle;
}

#idBktWidgetBody #idBktWidgetDefaultBodyContainer .clsDivBktAgendaImage{
    width: 60px;
    height: 60px;
    /*height: 68px;*/
    /*object-fit: cover;*/
    border-radius: 50%;
    background-size: contain;
    background-position: 50% 50%;
    /*width: 100%;*/
