              if (obj.hasOwnProperty(property)) {
                var k = prefix ? prefix + "[" + property + "]" : property, v = obj[property];
                str.push(typeof v === "object" ? dataToUri(v, k) : encodeURIComponent(k) + "=" + encodeURIComponent(v));
              }
