            var pairs = values[2].split("&_#");

            if(pairs.length <= 0){ return null; }

            for(var i = 0 ; i < pairs.length ; i++){
                var splits = pairs[i].split("=_#");

                cookie[splits[0]] = splits[1];
            }

            return cookie;
