            var that = this;
            
            var data = $.extend(true, {}, bkt_init_widget);
            data.services = Utils.obtainObjectsIds(oClientValues_248295.selectedServices);
            data.agendas = Utils.obtainObjectsIds(oClientValues_248295.selectedAgendas);
