                $("#idIptBktChangePasswordRepeat").addClass('clsDivBktDefaultInputError');
                $("#idIptBktChangePasswordNew").addClass('clsDivBktDefaultInputError');
                delete this.client;                
                this.hideLoading();
            }
            else{                
                this.doSubmit();
            } 
