        printTicket: function(ev){
            var that = this;

            var event = '';

            if($(ev.target).parent().parent().hasClass('clsDivBktAccountHistoryContentDataMobile')){
                event = $(ev.target).parent().parent().parent().parent().attr('id');
            }
